  // Valid Spotify URI for supported content types. Must be exact URI returned by Spotify Search Tool. Supported types: tracks (spotify:track:4iV5W9uYEdYUVa79Axb7Rh), albums (spotify:album:1A2GTWGtFfWp7KSQTwWOyo), playlists (spotify:playlist:37i9dQZF1DX0XUsuxWHRQd), artists (spotify:artist:1uNFoZAHBGtllmzznpCI3s), podcast shows (spotify:show:5CfCWKI5pZ28U0uOzXkDHe), podcast episodes (spotify:episode:512ojhOuo1ktJprKbVcKyQ), audiobooks (spotify:show:7iHfbu1YPACw6oZPAFJtqe). Do not generate or infer URIs.
  uri: string;
}): Promise<CallToolResult<{
  // Library save state of the item after this operation. NOT_SAVED when the removal succeeded; no other value is returned. Absent when the operation failed, because the resulting state is unknown.
  library_status?: "LIBRARY_STATUS_UNSPECIFIED" | "SAVED" | "NOT_SAVED" | "NOT_SAVABLE" | "PRE_SAVED";
  // Human-readable message describing the result. Must be displayed exactly as returned. Do not alter, infer, or fabricate values.
  message?: string;
}>>; };
```

